 void emailSettings(){try{JSONObject me=vault.copy();LinearLayout b=col();pad(b,16);EditText email=field(b,"Электронная почта",false);email.setInputType(33);email.setText(me.optString("email"));paragraph(b,me.optBoolean("email_verified")?"✓ Адрес подтверждён":"Адрес используется для входа. Подтверждение почты требует подключения отправки писем на сервере.");space(b,12);b.addView(button("Сохранить e-mail",true,()->{String value=email.getText().toString().trim();task(()->{vault.profile(api.call("/email/link",new JSONObject().put("email",value),vault.token()));runOnUiThread(()->Toast.makeText(this,"E-mail сохранён",Toast.LENGTH_SHORT).show());});}));space(b,8);b.addView(button("Отправить код подтверждения",false,()->task(()->{api.call("/email/request",new JSONObject(),vault.token());runOnUiThread(()->{LinearLayout codeBox=col();pad(codeBox,16);EditText code=field(codeBox,"Код из письма",false);code.setInputType(2);dialog().setTitle("Подтвердить почту").setView(codeBox).setNegativeButton("Отмена",null).setPositiveButton("Подтвердить",(x,w)->{String c=code.getText().toString().trim();task(()->{vault.profile(api.call("/email/verify",new JSONObject().put("code",c),vault.token()));runOnUiThread(()->Toast.makeText(this,"Почта подтверждена",Toast.LENGTH_SHORT).show());});}).show();});})));sheet("✉ Электронная почта",b);}catch(Exception e){error(Api.message(e));}}
 String makeThumb(String local)throws Exception{byte[] bytes=MediaFiles.bytes(this,local);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/180);o.inJustDecodeBounds=false;Bitmap bm=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bm==null)return "";float scale=Math.min(1,180f/Math.max(bm.getWidth(),bm.getHeight()));Bitmap small=Bitmap.createScaledBitmap(bm,Math.max(1,(int)(bm.getWidth()*scale)),Math.max(1,(int)(bm.getHeight()*scale)),true);ByteArrayOutputStream out=new ByteArrayOutputStream();small.compress(Bitmap.CompressFormat.JPEG,45,out);if(small!=bm)small.recycle();bm.recycle();return out.size()<=7000?Crypto.b64(out.toByteArray()):"";}
 void photoPreview(JSONObject m,ImageView view){final Vault account=vault;String key=m.optString("id"),cacheKey=key+(m.has("local")?":full":":thumb");Bitmap cached=mediaCache.get(cacheKey);if(cached!=null){view.setImageBitmap(cached);return;}work.execute(()->{try{byte[] bytes=m.has("local")?MediaFiles.bytes(this,m.getString("local")):Crypto.un64(m.optString("thumb"));if(bytes.length==0)return;BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/700);o.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(image!=null&&vault==account){mediaCache.put(cacheKey,image);runOnUiThread(()->{if(vault==account)view.setImageBitmap(image);});}}catch(Exception ignored){}});}
 void addLink(LinearLayout bubble,JSONObject link,boolean group){String url=link.optString("url");try{java.net.URI uri=new java.net.URI(url);if(!("https".equals(uri.getScheme())||"http".equals(uri.getScheme()))||uri.getHost()==null||uri.getUserInfo()!=null)return;}catch(Exception e){return;}space(bubble,10);LinearLayout card=col();pad(card,10);GradientDrawable bg=shape(light?0xffedf5ff:0xff17293d,12);bg.setStroke(dp(1),light?0xffbfdbf8:0xff365879);card.setBackground(bg);TextView provider=label(link.optString("site","Ссылка"),12,light?0xff3776b4:0xff9acfff);provider.setTypeface(null,1);card.addView(provider);space(card,4);TextView title=label(link.optString("title"),15,TEXT);title.setTypeface(null,1);title.setMaxLines(3);card.addView(title);if(!link.optString("author").isEmpty()){space(card,4);card.addView(label(link.optString("author"),12,MUTED));}String video=LinkCards.youtube(url);if(!video.isEmpty()){space(card,8);FrameLayout frame=new FrameLayout(this);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(light?0xffd6e3f4:0xff223954);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));TextView play=label("▶",34,0xffffffff);play.setGravity(Gravity.CENTER);play.setShadowLayer(dp(5),0,dp(1),0xff263243);frame.addView(play,new FrameLayout.LayoutParams(-1,-1));card.addView(frame,new LinearLayout.LayoutParams(group?-1:dp(222),dp(150)));Bitmap cached=mediaCache.get("yt:"+video);if(cached!=null)image.setImageBitmap(cached);else Art.fetch.execute(()->{try{Bitmap pic=LinkCards.thumbnail(video);if(pic!=null){mediaCache.put("yt:"+video,pic);runOnUiThread(()->image.setImageBitmap(pic));}}catch(Exception ignored){}});}TextView open=label("Открыть ↗",12,light?0xff3672ab:0xff9acfff);space(card,7);card.addView(open);card.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){error("Не удалось открыть ссылку");}});bubble.addView(card,new LinearLayout.LayoutParams(group?-1:-2,-2));}


 void cloudSettings(){LinearLayout b=col();pad(b,16);paragraph(b,"Сообщения и миниатюры сохраняются на сервере в зашифрованном виде. Чтобы восстановить их на другом телефоне, сохрани защищённую паролем копию ключей. Фото и голосовые до 25 МБ также загружаются на сервер в зашифрованном виде.");space(b,14);EditText password=field(b,"Твой пароль аккаунта",true);b.addView(button("Защитить ключи в облаке",true,()->{String pass=password.getText().toString();task(()->{JSONObject login=api.call("/login",new JSONObject().put("nick",vault.nick()).put("password",pass),"");api.call("/key-backup",new JSONObject().put("backup",Crypto.exportBackup(vault.keyBackup(),pass.toCharArray())),login.getString("token"));runOnUiThread(()->Toast.makeText(this,"Копия ключей защищена паролем и сохранена",Toast.LENGTH_LONG).show());});}));space(b,12);paragraph(b,"После сохранения ключей доступ к аккаунту на новом телефоне восстанавливается по e-mail или нику и паролю. Выбирай длинный уникальный пароль: он защищает копию ключей.");sheet("Защита и история",b);}


 String audience(JSONObject r){int n=r.optJSONArray("members")==null?0:r.optJSONArray("members").length();String[] words=r.optString("kind").equals("channel")?new String[]{"подписчик","подписчика","подписчиков"}:new String[]{"участник","участника","участников"};int x=n%100,y=n%10;return n+" "+words[x>=11&&x<=14?2:y==1?0:y>=2&&y<=4?1:2];}
