 void addComments(LinearLayout bubble,JSONObject m){String rid=Conversation.room(chat),mid=m.optString("id");int count=0;try{JSONArray a=vault.copy().getJSONArray("messages");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x.optString("peer").equals("thread:"+rid+":"+mid)&&!x.optString("kind").equals("control"))count++;}}catch(Exception ignored){}space(bubble,10);View divider=new View(this);divider.setBackgroundColor(light?0xffdce5ef:0xff405065);bubble.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));TextView c=label("◌  "+(count==0?"Комментировать":count+" · Комментарии")+"   ›",14,light?0xff3470ac:0xff9bcfff);c.setTypeface(null,1);c.setPadding(0,dp(12),0,dp(2));c.setOnClickListener(v->openComments(rid,mid));bubble.addView(c,new LinearLayout.LayoutParams(-1,-2));}
 void videoCover(JSONObject m,ImageView image){final Vault account=vault;String vid=m.optString("cloud_video"),cacheKey="video-cover-hq:"+vid;Bitmap cached=mediaCache.get(cacheKey);if(cached!=null){image.setImageBitmap(cached);return;}try{byte[] bytes=Crypto.un64(m.optString("thumb"));if(bytes.length>0){Bitmap thumb=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(thumb!=null)image.setImageBitmap(thumb);}}catch(Exception ignored){}
  if(!loadingImages.add(cacheKey))return;Art.fetch.execute(()->{try{for(int attempt=0;attempt<4&&vault==account;attempt++)try{JSONObject result=api.call("/video-cover/"+vid,null,account.token());byte[] bytes=Crypto.un64(result.getString("photo"));Bitmap cover=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(cover!=null&&vault==account)runOnUiThread(()->{if(vault!=account)return;mediaCache.put(cacheKey,cover);image.setImageBitmap(cover);updateCoverViews(root,vid,cover);});return;}catch(Api.Failure failure){if(failure.status!=409)return;try{Thread.sleep(1200);}catch(InterruptedException stop){Thread.currentThread().interrupt();return;}}catch(Exception unavailable){return;}}finally{runOnUiThread(()->loadingImages.remove(cacheKey));}});
 }
 void updateCoverViews(View v,String vid,Bitmap bitmap){if(v instanceof ImageView&&("video:"+vid).equals(v.getTag()))((ImageView)v).setImageBitmap(bitmap);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)updateCoverViews(g.getChildAt(i),vid,bitmap);}}

 void addVideo(LinearLayout b,JSONObject m,boolean group){boolean round=m.optBoolean("round");AspectMediaFrame frame=new AspectMediaFrame(this,round);ImageView image=new AspectMediaFrame.Cover(this,frame);image.setTag("video:"+m.optString("cloud_video"));frame.addView(image,new FrameLayout.LayoutParams(-1,-1));videoCover(m,image);UiIcon play=new UiIcon(this,"play",0xffffffff);play.setBackground(shape(0xa5122035,28));FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(dp(62),dp(62),Gravity.CENTER);frame.addView(play,pp);TextView badge=label((round?"Кружок":"MP4")+" · "+size(m.optLong("size"))+"  ⛶",11,0xffffffff);badge.setPadding(dp(10),dp(6),dp(10),dp(6));badge.setBackgroundColor(0x99091221);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.RIGHT);frame.addView(badge,bp);frame.setOnClickListener(v->openMedia(m));b.addView(frame,new LinearLayout.LayoutParams(round?dp(218):group?-1:Math.min(dp(250),getResources().getDisplayMetrics().widthPixels-dp(100)),-2));}


 void soundPicker(){LinearLayout b=col();for(int i=0;i<Notices.TONE_NAMES.length;i++){final int n=i;LinearLayout line=row();TextView choose=button((Notices.tone(this)==i?"✓ ":"")+Notices.TONE_NAMES[i],Notices.tone(this)==i,()->{Notices.prefs(this).edit().putInt("tone",n).apply();previewTone(n);Toast.makeText(this,"Звук выбран: "+Notices.TONE_NAMES[n],Toast.LENGTH_SHORT).show();});line.addView(choose,new LinearLayout.LayoutParams(0,dp(48),1));TextView listen=label("▶",20,TEXT);listen.setGravity(Gravity.CENTER);listen.setOnClickListener(v->previewTone(n));line.addView(listen,new LinearLayout.LayoutParams(dp(48),dp(48)));b.addView(line);space(b,7);}space(b,8);b.addView(button("Громкость уведомлений Android",false,()->startActivity(new Intent(Settings.ACTION_SOUND_SETTINGS))));space(b,8);paragraph(b,"Новые мелодии звучат ярче. Итоговая громкость зависит от системной громкости уведомлений и режима «Не беспокоить».");sheet("♫ Выбери звук",b);}
 void previewTone(int index){try{MediaPlayer sound=MediaPlayer.create(this,Notices.TONES[index],new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_NOTIFICATION).build(),0);if(sound!=null){sound.setVolume(1,1);sound.setOnCompletionListener(MediaPlayer::release);sound.start();}}catch(Exception e){error("Не удалось воспроизвести звук");}}

 void deletePost(JSONObject m){String target=m.optString("peer");dialog().setTitle("Удалить для всех?").setMessage("Сообщение, вложение на сервере и комментарии к этому посту будут удалены.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->task(()->{if(m.optBoolean("out"))ChatService.register(api,vault,m);JSONObject result=api.call("/posts/delete",new JSONObject().put("mid",m.getString("id")).put("room",Conversation.community(target)?Conversation.room(target):""),vault.token());vault.deletion(result);mediaCache.evictAll();runOnUiThread(()->{renderMessages();Toast.makeText(this,result.optBoolean("media_cleanup_pending")?"Пост удалён. Завершаем очистку файла.":"Удалено вместе с вложением на сервере",Toast.LENGTH_LONG).show();});})).show();}
 void deleteRoom(JSONObject room){dialog().setTitle("Удалить «"+room.optString("title")+"»?").setMessage("Все публикации, комментарии и файлы этого сообщества будут удалены для всех участников. Отменить это действие нельзя.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->task(()->{JSONObject r=api.call("/room/delete",new JSONObject().put("room",room.getString("id")),vault.token());vault.deletion(r);runOnUiThread(()->chats());})).show();}
 void animateEnter(View view,int index){if(!Notices.prefs(this).getBoolean("motion",true))return;view.setAlpha(0);view.setTranslationY(dp(12));view.setScaleX(.975f);view.setScaleY(.975f);view.animate().alpha(1).translationY(0).scaleX(1).scaleY(1).setStartDelay(Math.min(index,5)*35L).setDuration(260).setInterpolator(new android.view.animation.DecelerateInterpolator());}
