 void capsule(){try{LinearLayout b=col();paragraph(b,"Личная капсула дня — мысли и планы, которые видишь только ты. Сохраняется в зашифрованном хранилище этого аккаунта на телефоне.");space(b,12);EditText note=field(b,"Что хочется сохранить сегодня?",false);note.setSingleLine(false);note.setMinLines(3);String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date());note.setText(vault.bucket("capsules").optString(day));b.addView(button("Сохранить капсулу ✦",true,()->task(()->{synchronized(vault){vault.bucket("capsules").put(day,note.getText().toString());vault.save();}runOnUiThread(()->Toast.makeText(this,"Капсула сохранена",Toast.LENGTH_SHORT).show());})));space(b,12);JSONObject all=vault.bucket("capsules");all.keys().forEachRemaining(date->{TextView entry=label(date+" · "+all.optString(date),13,MUTED);pad(entry,8);b.addView(entry);});sheet("✦ Капсула дня",b);}catch(Exception e){error(Api.message(e));}}

